INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(111506, 'ruRU', '', 'Слава тебе на поле битвы.', 24330),
(111507, 'ruRU', '', 'Пусть взгляд Одина даст тебе силу.', 24330),
(111508, 'ruRU', '', 'Стремись быть достойным.', 24330),
(111539, 'ruRU', '', 'Нужна книга?', 24330),
(111540, 'ruRU', '', 'Поискать для тебя что-нибудь?', 24330),
(111541, 'ruRU', '', 'Да?', 24330),
(111542, 'ruRU', '', 'Иди с мудростью.', 24330),
(111543, 'ruRU', '', 'Мир — учитель, а мы — его ученики.', 24330),
(111544, 'ruRU', '', 'Береги себя.', 24330),
(111545, 'ruRU', '', 'Как насчёт того, чтобы найти хорошую книгу для чтения?', 24330),
(111546, 'ruRU', '', 'Я готов к оформлению.', 24330),
(111547, 'ruRU', '', 'Тихо!', 24330),
(111585, 'ruRU', '', 'Привет, $c. Чувствую, у тебя ко мне дело.', 24330),
(111586, 'ruRU', '', 'Земля и камень восстанут, чтобы защитить наш мир от демонического натиска!', 24330),
(111588, 'ruRU', '', 'Ах да! Весьма прилежный был малый, жаждал услышать истории о Тире, страже титанов.$b$bЯ рассказал ему о битве между Галакрондом и Тиром, и о том, как Калекгос увидел отрубленную руку Тира на Покое Галакронда. Гэлфорд очень разволновался и ушёл.$b$bТвой друг в безопасности?', 24330),
(111593, 'ruRU', '', 'Покой Галакронда может быть опасен. Возможно, заклинание следопыта окажется полезным.', 24330),
(111599, 'ruRU', '', 'Твой друг пришёл в поисках ответов, его разум захлестнули воспоминания, хранящиеся в Искре благородного наблюдателя. Он узнал о древней битве Тира против Галакронда и о руке, которую тот потерял в пасти дракона.', 24330),
(111608, 'ruRU', '', 'Агх!! Заставь их остановиться! Прошу, заставь их остановиться!', 24330),
(111617, 'ruRU', '', 'Пылающий Легион снова атакует Азерот. Мир в хаосе, но Подземье грозит более насущная угроза.$b$bЯ не могу охотиться на шакалов, пока волки рычат у моего порога!', 24330),
(111630, 'ruRU', '', 'Серебряная рука была выкована Йотуном, ближайшим другом Тира на протяжении многих веков. Когда Тир нашёл доказательства предательства Локена, именно Йотун остался, чтобы сдержать погоню павшего наблюдателя.', 24330),
(111634, 'ruRU', '', 'Твой друг искал Йотуна, но Искра не предупредила его о жестоком проклятии, которым Локен искривил разум наблюдателя. Паладин бросился к ущелью к югу отсюда, лишь чтобы встретить свою гибель.', 24330),
(111636, 'ruRU', '', 'Привет.', 24330),
(111638, 'ruRU', '', 'Да?', 24330),
(111644, 'ruRU', '', 'Больше не нужно слов.', 24330),
(111647, 'ruRU', '', 'Начнём. Идём, Терин.', 24330),
(111648, 'ruRU', '', 'Понятно.', 24330),
(111650, 'ruRU', '', 'Талисра, ты ведь не серьёзно? Тратить своё время на это... создание!', 24330),
(111655, 'ruRU', '', 'Нар''тала вас манари...', 24330),
(111660, 'ruRU', '', 'Я искал тебя повсюду. Ты нашёл... О, нет...', 24330),
(111662, 'ruRU', '', 'Я тоже это почувствовал...', 24330),
(111663, 'ruRU', '', 'В тот день, когда его изгнали...', 24330),
(111664, 'ruRU', '', 'Этот голод... этот страх...', 24330),
(111667, 'ruRU', '', 'Такое смятение... такая ярость...', 24330),
(111668, 'ruRU', '', 'Талисра! Ты в порядке?', 24330),
(111671, 'ruRU', '', 'Мне искренне жаль. Похоже, твоего друга раздавило. Что могло...', 24330),
(111673, 'ruRU', '', 'Что это за сущность, о которой говорит великан? Я хотел бы поговорить с тобой, $n.', 24330),
(111674, 'ruRU', '', 'Расскажи мне, что происходит. Что ты ищешь, $n?', 24330),
(111676, 'ruRU', '', 'Благое дело. Я встану рядом с тобой против могущества Йотуна, $n. Будь готов!', 24330),
(111755, 'ruRU', '', '<Тёмная фигура мирно сидит в парке, словно полузабытое воспоминание о давно умершей личности из прошлого. Она, кажется, узнаёт твой посох и тепло приветствует тебя, принимая тебя за кого-то другого.>$b$bПривет, Алоди, старый друг! Присоединишься ко мне? Одно из самых возвышенных удовольствий в жизни — сидеть в парке со знакомой старой книгой.$b$bПожалуй, я посажу здесь саженец, чтобы в будущие годы маги могли сидеть в тени небольшого дерева.', 24330),
(111758, 'ruRU', '', 'Я помогу, если придётся. Ты сосредоточил столько силы в этом посохе — я беспокоюсь, что с тобой станет!', 24330);
